    #region Helper Methods
    private string GetSelectedMaLopBo()
    {
        if (string.IsNullOrEmpty(SelectedLop)) return string.Empty;
        var lop = thData?.danhSachLopList?.FirstOrDefault(l => l.IdLopBo.ToString() == SelectedLop);
        return lop?.MaLopBo ?? string.Empty;
    }

    private string GetTenKhoiLop()
    {
        if (!string.IsNullOrEmpty(MaKhoiLopChuNhiem))
        {
            var khoi = thData.danhSachKhoiList.FirstOrDefault(k => k.MaKhoiBo.ToString() == MaKhoiLopChuNhiem);
            return khoi?.TenKhoi ?? "Khối chủ nhiệm";
        }
        return "Khối chủ nhiệm";
    }

    #region Teacher Methods
    private async Task CheckGiaoVienChuNhiem()
    {
        if (userRole == "GiaoVien" && giaovien != null)
        {
            if (giaovien.ma_lop != null && giaovien.ma_lop > 0)
            {
                IsGiaoVienChuNhiem = true;

                var lopChuNhiem = thData.danhSachLopList.FirstOrDefault(l => l.IdLopBo == giaovien.ma_lop);
                if (lopChuNhiem != null)
                {
                    tenLopChuNhiem = lopChuNhiem.TenLop;
                    LopChuNhiemId = lopChuNhiem.IdLopBo;
                    MaKhoiLopChuNhiem = lopChuNhiem.MaKhoiBo.ToString();

                    SelectedLop = LopChuNhiemId.ToString();
                    SelectedKhoi = MaKhoiLopChuNhiem;
                }
                else
                {
                    IsGiaoVienChuNhiem = false;
                    tenLopChuNhiem = "Lớp không tồn tại";
                }
            }
            else
            {
                IsGiaoVienChuNhiem = false;
                tenLopChuNhiem = "Chưa có lớp";
            }
        }
    }

    private List<KeyValuePair<object, string>> GetTeacherKhoiOptions()
    {
        if (userRole != "GiaoVien" || !phanCongGiangDayList.Any())
            return KhoiLopOptions;

        if (IsGiaoVienChuNhiem && !string.IsNullOrEmpty(MaKhoiLopChuNhiem))
        {
            var khoi = thData.danhSachKhoiList.FirstOrDefault(k => k.MaKhoiBo.ToString() == MaKhoiLopChuNhiem);
            if (khoi != null)
            {
                return new List<KeyValuePair<object, string>>
                {
                    new KeyValuePair<object, string>(khoi.MaKhoiBo, khoi.TenKhoi)
                };
            }
        }

        var teacherLopHocIds = phanCongGiangDayList
            .Where(p => p.MaGiaoVien == maUser)
            .Select(p => p.IdLopBo)
            .Distinct()
            .ToList();

        var teacherKhoiIds = thData.danhSachLopList
             .Where(l => teacherLopHocIds.Contains(l.IdLopBo))
             .Select(l => l.MaKhoiBo)
             .Distinct()
             .ToList();

        return KhoiLopOptions
            .Where(k => teacherKhoiIds.Contains(k.Key))
            .ToList();
    }

    private List<KeyValuePair<object, string>> GetTeacherLopHocOptions()
    {
        if (userRole != "GiaoVien" || !phanCongGiangDayList.Any())
            return LopHocOptions;

        if (IsGiaoVienChuNhiem && LopChuNhiemId > 0)
        {
            var lopChuNhiem = thData.danhSachLopList.FirstOrDefault(l => l.IdLopBo == LopChuNhiemId);
            if (lopChuNhiem != null)
            {
                return new List<KeyValuePair<object, string>>
                {
                    new KeyValuePair<object, string>(lopChuNhiem.IdLopBo, lopChuNhiem.TenLop)
                };
            }
        }

        var teacherLopHocIds = phanCongGiangDayList
            .Where(p => p.MaGiaoVien == maUser)
            .Select(p => p.IdLopBo)
            .Distinct()
            .ToList();

        if (!string.IsNullOrEmpty(SelectedKhoi) && !string.IsNullOrWhiteSpace(SelectedKhoi))
        {
            teacherLopHocIds = thData.danhSachLopList
                .Where(l => teacherLopHocIds.Contains(l.IdLopBo) && l.MaKhoiBo.ToString() == SelectedKhoi)
                .Select(l => l.IdLopBo)
                .Distinct()
                .ToList();
        }

        return LopHocOptions
            .Where(l => teacherLopHocIds.Contains((int)l.Key))
            .ToList();
    }

    #endregion
    #endregion

    #region Filter Logic
    private void GetDataOfKhoi()
    {
        KhoiLopOptions.Clear();
        foreach (var khoilop in thData.danhSachKhoiList)
        {
            KhoiLopOptions.Add(new KeyValuePair<object, string>(khoilop.MaKhoiBo, khoilop.TenKhoi));
        }
        UpdateKhoiLopOptions();
    }

    private void GetDataOfLop()
    {
        LopHocOptions.Clear();
        foreach (var lophoc in thData.danhSachLopList)
        {
            LopHocOptions.Add(new KeyValuePair<object, string>(lophoc.IdLopBo, lophoc.TenLop));
        }
    }


    private void UpdateKhoiLopOptions()
    {
        if (userRole != "GiaoVien")
        {
            FilteredKhoiLopOptions = KhoiLopOptions;
        }
        else
        {
            FilteredKhoiLopOptions = GetTeacherKhoiOptions();
        }
    }

    private async Task OnKhoiLopChange(ChangeEventArgs e)
    {
        if (IsGiaoVienChuNhiem) return;

        SelectedKhoi = e.Value?.ToString() ?? string.Empty;
        SelectedLop = string.Empty;
        SelectedMonHoc = string.Empty;

        UpdateLopHocOptions();

        if (FilteredLopHocOptions.Any())
        {
            SelectedLop = FilteredLopHocOptions.First().Key.ToString() ?? string.Empty;
            await LoadMonHocList();          // Load môn học theo lớp mới
            await LoadLockStatus();           // Load trạng thái khóa
        }

        StateHasChanged();
    }

    private void UpdateLopHocOptions()
    {
        if (userRole != "GiaoVien")
        {
            FilteredLopHocOptions = LopHocOptions
                .Where(lop =>
                    string.IsNullOrEmpty(SelectedKhoi) ||
                    thData.danhSachLopList.Any(l => l.IdLopBo.ToString() == lop.Key.ToString() && l.MaKhoiBo.ToString() == SelectedKhoi))
                .ToList();
        }
        else
        {
            FilteredLopHocOptions = GetTeacherLopHocOptions();
        }
    }

    private void UpdateMonHocOptions()
    {
        // GiaoVien xem tất cả môn được cấu hình theo lớp (không lọc theo phân công)
        // Quyền edit được kiểm soát riêng qua IsMonHocPhanCong + CanEdit
        FilteredMonHocOptions = monHocList
            .Select(m => new KeyValuePair<object, string>(m.idmonhocso, m.ten_mon_hoc))
            .ToList();
    }

    private async Task OnLopHocChange(ChangeEventArgs e)
    {
        if (IsGiaoVienChuNhiem) return;

        SelectedLop = e.Value?.ToString() ?? string.Empty;
        SelectedMonHoc = string.Empty; // Reset môn học

        if (!string.IsNullOrEmpty(SelectedLop))
        {
            isLoading = true;
            StateHasChanged();

            try
            {
                // Load danh sách môn học cho lớp mới
                await LoadMonHocList();

                // Load trạng thái khóa cho lớp mới
                await LoadLockStatus();

                // KHÔNG cần gọi LoadDiemHocSinh ở đây vì component con sẽ tự load
                // khi SelectedMonHoc được cập nhật
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Lỗi khi đổi lớp: {ex.Message}");
                await JS.InvokeVoidAsync("alert", "Lỗi khi tải dữ liệu cho lớp mới");
            }
            finally
            {
                isLoading = false;
                StateHasChanged();
            }
        }

        // Cập nhật options cho môn học (đã được LoadMonHocList xử lý)
        UpdateMonHocOptions();

        StateHasChanged();
    }

    private async Task OnMonHocChange(ChangeEventArgs e)
    {
        SelectedMonHoc = e.Value?.ToString() ?? string.Empty;
        if (!string.IsNullOrEmpty(SelectedMonHoc))
        {
            await LoadLockStatus();           // Cập nhật khóa theo môn mới
        }
        StateHasChanged();
    }

    private void SwitchView(string view)
    {
        CurrentView = view;
    }
    #endregion

    #region Load Data (Môn học, Lock, Học sinh...)
    private async Task LoadLockStatus()
    {
        try
        {
            isSystemLocked = false;
            isClassSubjectLocked = false;

            DateTime now = DateTime.Now;
            int namHocInt = int.Parse(SelectedNamHoc.Split('-')[0]);
            int hocKyInt = int.Parse(SelectedHocKy);
            string currentNamHoc = await BrowserStorageService.GetItem(JS, "currentNamHoc") ?? "2025-2026";

            var thoiGianNhapDiems = await DiemService.hGetThoiGianNhapDiem(
                namHocInt,
                hocKyInt,
                selectedCapHoc!,
                maTruongBo!
            );

            bool isInTimeRange = thoiGianNhapDiems.Any(x =>
                x.TrangThai == 1 &&
                now >= x.ThoiGianBatDau &&
                now <= x.ThoiGianKetThuc
            );
            isSystemLocked = !isInTimeRange;

            if (!string.IsNullOrEmpty(SelectedLop) && !string.IsNullOrEmpty(SelectedMonHoc))
            {
                var khoaSoDiems = await DiemService.hGetKhoaSoDiem(
                    selectedCapHoc!,
                    maTruongBo!,
                    currentNamHoc,
                    hocKyInt,
                    Convert.ToInt32(SelectedLop)
                );

                isClassSubjectLocked = khoaSoDiems.Any(x =>
                    x.IdLopBo == SelectedLop &&
                    x.IdMonHoc == SelectedMonHoc &&
                    x.IsLock
                );
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi LoadLockStatus: {ex.Message}");
            isSystemLocked = true;
            isClassSubjectLocked = true;
        }
        finally
        {
            StateHasChanged();
        }
    }

    private async Task LoadMonHocList()
    {
        try
        {
            if (string.IsNullOrEmpty(SelectedLop))
            {
                monHocList = new List<MonHocDTO>();
                FilteredMonHocOptions = new List<KeyValuePair<object, string>>();
                SelectedMonHoc = string.Empty;
                return;
            }

            // Lấy MaLopBo từ SelectedLop (IdLopBo)
            var lop = thData.danhSachLopList.FirstOrDefault(l => l.IdLopBo.ToString() == SelectedLop);
            if (lop == null)
            {
                monHocList = new List<MonHocDTO>();
                FilteredMonHocOptions = new List<KeyValuePair<object, string>>();
                SelectedMonHoc = string.Empty;
                return;
            }

            CauHinhMonData = await DiemService.hGetCauHinhLopMon(
                selectedCapHoc!,
                maTruongBo!,
                SelectedNamHoc!,
                SelectedHocKy,
                lop.MaLopBo   
            );

            var allMonHoc = await DaoTaoService.hGetMonHoc(selectedCapHoc);

            var monHocCauHinhIds = CauHinhMonData
                .Where(x => x.IsHienThi == 1)
                .Select(x => x.IdMonHocSo)
                .Distinct()
                .ToList();

            monHocList = allMonHoc
                .Where(m => monHocCauHinhIds.Contains(m.idmonhocso))
                .ToList();

            UpdateMonHocOptions();

            // Nếu có môn học, chọn môn đầu tiên
            if (monHocList.Any())
            {
                SelectedMonHoc = monHocList.First().idmonhocso;
                Console.WriteLine($"[Cha] Đã chọn môn học mặc định: {SelectedMonHoc}");
            }
            else
            {
                SelectedMonHoc = string.Empty;
                Console.WriteLine("[Cha] Lớp này không có môn học nào được cấu hình");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi tải danh sách môn học: {ex.Message}");
            monHocList = new List<MonHocDTO>();
            FilteredMonHocOptions = new List<KeyValuePair<object, string>>();
            SelectedMonHoc = string.Empty;
        }
    }

    private async Task LoadData()
    {
        try
        {
            isLoading = true;
            StateHasChanged();

            if (userRole == "GiaoVien")
            {
                if (string.IsNullOrEmpty(SelectedLop) || string.IsNullOrEmpty(SelectedMonHoc))
                {
                    await JS.InvokeVoidAsync("alert", "Giáo viên cần chọn lớp và môn học để đánh giá");
                    return;
                }
            }

            if (IsGiaoVienChuNhiem && (string.IsNullOrEmpty(SelectedLop) || SelectedLop != LopChuNhiemId.ToString()))
            {
                SelectedLop = LopChuNhiemId.ToString();
                await LoadMonHocList();
                await LoadLockStatus();
            }

            await Task.Delay(100);
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    private async Task LoadLevelFromStorage()
    {
        try
        {
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

            if (string.IsNullOrEmpty(selectedCapHoc))
            {
                selectedCapHoc = "02";
                await BrowserStorageService.SetItem(JS, "selectedLevel", selectedCapHoc);
                await BrowserStorageService.SetItem(JS, "selectedLevelText", "Cấp Tiểu học");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi đọc cấp học từ Local Storage: {ex.Message}");
            selectedCapHoc = "02";
        }
    }

    private void SetDefaultKhoiAndLopIfNeeded()
    {
        if (IsGiaoVienChuNhiem)
            return;

        if (string.IsNullOrEmpty(SelectedKhoi) && FilteredKhoiLopOptions.Any())
        {
            SelectedKhoi = FilteredKhoiLopOptions.First().Key.ToString() ?? string.Empty;
        }

        UpdateLopHocOptions();

        if (string.IsNullOrEmpty(SelectedLop) && FilteredLopHocOptions.Any())
        {
            SelectedLop = FilteredLopHocOptions.First().Key.ToString() ?? string.Empty;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadLevelFromStorage();
        var authState = await AuthenticationStateProvider.GetAuthenticationStateAsync();
        var user = authState.User;

        if (user.Identity is not null && user.Identity.IsAuthenticated)
        {
            // Lấy MaUser
            maUser = user.FindFirst("MaUser")?.Value ?? "Không tìm thấy";
            
            // Lấy Role
            userRole = user.FindFirst(ClaimTypes.Role)?.Value ?? "Không có role";
        }

        SelectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2023-2024";
        SelectedHocKy = await BrowserStorageService.GetItem(JS, "selectedHocKy") ?? "1";

        maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);

        if (userRole == "GiaoVien")
        {
            giaovien = await TruongService.hGetGiaoVienByIdAsync(maUser, maTruongBo, SelectedNamHoc);
        }

        thData.danhSachKhoiList = await TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc);
        thData.danhSachLopList = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, SelectedNamHoc);
        thData.danhSachMonHocList = await DaoTaoService.hGetMonHoc(selectedCapHoc);
        var lopDict = thData.danhSachLopList
        .Where(l => l.IdLopBo > 0)
        .ToDictionary(l => l.IdLopBo,
                  l => (TenLop: l.TenLop ?? "", MaKhoiBo: (l.MaKhoiBo ?? "").PadLeft(2, '0')));
        // Load toàn bộ phân công của trường (dùng để lọc khung giáo viên)
        phanCongGiangDayList = await TruongService.hGetDanhSachPhanCongGiangDay(maTruongBo, SelectedNamHoc, null, lopDict);

        // Nếu là Giáo Viên: load riêng phân công cá nhân để kiểm tra quyền edit
        if (userRole == "GiaoVien" && maUser != "Chưa có" && maUser != "Không tìm thấy")
        {
            phanCongCaNhanList = await TruongService.hGetPhanCongGiangDayByMaGiaoVien(
               maTruongBo, SelectedNamHoc,maUser, null, lopDict
            );
        }
        else
        {
            // Admin: không cần filter theo phân công
            phanCongCaNhanList = new();
        }

        GetDataOfKhoi();
        GetDataOfLop();

        await CheckGiaoVienChuNhiem();

        SetDefaultKhoiAndLopIfNeeded();

        if (!string.IsNullOrEmpty(SelectedLop))
        {
            await LoadMonHocList();
            await LoadLockStatus();
        }

        StateHasChanged();
    }
